-- Ethiopia administrative level 3 (Woredas)
-- Source: ETH_Woredas.shp
-- Records: 1141

DROP TABLE IF EXISTS "eth_woredas" CASCADE;

CREATE TABLE "eth_woredas" (
    "OBJECTID" INTEGER,
    "admin3Name" TEXT,
    "admin3Pcod" TEXT,
    "admin3RefN" TEXT,
    "admin3AltN" TEXT,
    "admin3Al_1" TEXT,
    "admin2Name" TEXT,
    "admin2Pcod" TEXT,
    "admin1Name" TEXT,
    "admin1Pcod" TEXT,
    "admin0Name" TEXT,
    "admin0Pcod" TEXT,
    "date" DATE,
    "validOn" DATE,
    "validTo" DATE,
    "Shape_Leng" DOUBLE PRECISION,
    "Shape_Area" DOUBLE PRECISION,
    geom geometry(MultiPolygon, 4326) NOT NULL
);

COMMENT ON TABLE "eth_woredas" IS 'Ethiopia administrative level 3 (Woredas)';


CREATE INDEX "eth_woredas_geom_idx" ON "eth_woredas" USING GIST (geom);
